    <div class="house-mode-intro"><div><small>MAISON DES COMBATS</small><h3>{{ selected.title }}</h3><p>{{ selected.description }}</p></div><span class="house-no-xp">Sans XP</span></div>
    <template v-if="!active">
     <div v-if="mode==='pve'" class="house-trainer-picker"><div class="trainer-picker-title"><h4>Choisis ton adversaire</h4><input v-model="search" type="search" placeholder="Un dresseur…" aria-label="Rechercher un dresseur"></div><div class="house-trainers"><button v-for="t in filteredTrainers" :key="t.key" class="house-trainer" :class="{selected:config.trainerKey===t.key}" :aria-pressed="config.trainerKey===t.key" :data-house-trainer="t.key" @click="config.trainerKey=t.key"><img :src="portrait(t.portrait)" alt="" loading="lazy"><span><small>{{ t.role }}</small><b>{{ t.name }}</b><span class="trainer-species"><img v-for="id in t.species.slice(0,6)" :key="id" :src="`${$assetBase}img/pokemon/front/${id}.png`" alt="" loading="lazy"></span></span><i aria-hidden="true">{{ config.trainerKey===t.key?'✓':'+' }}</i></button></div><p v-if="!filteredTrainers.length" class="house-help">Aucun dresseur avec ce nom.</p><p class="house-help">Son équipe s’adapte à la tienne : même nombre de Pokémon, niveaux proches. Le PvE ne compte pas dans le classement et ne donne aucune récompense.</p></div>
     <form id="house-setup-form" @submit.prevent="create">
