export default{components:{HousePreparation,PokemonDetails},props:{duel:Object,rosters:Object,trainers:{type:Array,default:()=>[]},userId:Number,busy:Boolean,connected:Boolean,clock:Number},
 data(){return{mode:this.duel?.config?.mode||'1v1',config:{level:null,uniqueItems:false,money:0,pokemonStake:false,format:6,trainerKey:this.trainers[0]?.key||''},search:'',detail:null};},
 computed:{modes:()=>modes,selected(){return modes.find(m=>m.key===this.mode)||modes[0];},active(){return this.duel&&!['finished','cancelled'].includes(this.duel.phase);},filteredTrainers(){return this.trainers.filter(t=>t.name.toLocaleLowerCase().includes(this.search.toLocaleLowerCase()));},resultText(){const r=this.duel?.result;if(!r)return'';if(this.duel.config.mode==='pve')return r.pveLost?'Cet adversaire prend sa revanche.':'Entraînement terminé.';if(r.winners?.includes(this.userId))return'Votre camp remporte le duel !';const winners=r.winners||[r.winnerId];return this.duel.participants.filter(p=>p&&winners.includes(p.userId)).map(p=>p.username).join(' & ')+(r.winnerId?' remporte le duel.':'Le duel est terminé.');}},
 watch:{'duel.config.mode'(mode){if(mode)this.mode=mode;},trainers(list){if(!this.config.trainerKey)this.config.trainerKey=list[0]?.key||'';}},
 methods:{portrait(name){try{return portraits('./'+name);}catch{return'';}},create(){this.$emit('command','create',{...this.config,mode:this.mode,money:this.mode==='pve'?0:this.config.money,pokemonStake:this.mode==='1v1'&&this.config.pokemonStake});},action(name,data={},done){this.$emit('command',name,{id:this.duel?.id,revision:this.duel?.revision,...data},done);},inspect(p){this.action('inspect',{ownerId:p.ownerId,pokemonUuid:p.uuid},(ok,state)=>{if(ok&&state?.detail)this.detail=computerPokemonDetails(state.detail);});},cancel(){if(window.confirm('Annuler cette préparation ? Aucune mise ne sera prélevée.'))this.action('leave');},tabKey(event,key){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)||this.active)return;event.preventDefault();const i=modes.findIndex(m=>m.key===key),next=event.key==='Home'?0:event.key==='End'?3:(i+(event.key==='ArrowRight'?1:3))%4;this.mode=modes[next].key;this.$nextTick(()=>this.$el.querySelector('#house-mode-'+this.mode)?.focus());}}
};
